import {seed,holes,totalTarget,forecast,clock,advance} from './pace.js';
const $=s=>document.querySelector(s);
let groups=structuredClone(seed), minutes=0,view='overview',filter='all',search='',selected=6,notes=[];
try {const saved=JSON.parse(localStorage.getItem('fairway-v1'));if(saved&&Array.isArray(saved.groups)&&saved.groups.length===12&&saved.groups.every(g=>Number.isFinite(g.hole)&&g.hole>=1&&g.hole<=19&&Number.isFinite(g.elapsed)&&Number.isFinite(g.inHole)&&Number.isFinite(g.tee))){groups=saved.groups;minutes=saved.minutes||0;notes=saved.notes||[];}}catch{}
function persist(){try{localStorage.setItem('fairway-v1',JSON.stringify({groups,minutes,notes}));}catch{toast('Browser storage unavailable. Changes will last for this session.');}}
const duration=n=>`${Math.floor(n/60)}h ${String(n%60).padStart(2,'0')}m`;
const state=g=>{const f=forecast(g,groups);return f.complete?'complete':f.delay>10?'late':f.delay>5?'warn':'good';};
const label=g=>({complete:'Completed',late:'Behind pace',warn:'Watch pace',good:'On pace'})[state(g)];
const pill=g=>`<span class="status ${state(g)}">${label(g)}</span>`;
const forecastFor=g=>forecast(g,groups);
const coords=[[13,78],[20,63],[13,46],[23,28],[37,18],[48,31],[40,48],[49,65],[40,82],[57,84],[66,67],[60,49],[69,32],[82,18],[89,35],[81,52],[90,69],[78,83]];
function courseMap(){return `<div class="map"><span class="map-label">COURSE TRAFFIC · SCHEMATIC MAP</span><svg viewBox="0 0 800 350" preserveAspectRatio="none" aria-hidden="true"><defs><pattern id="trees" width="29" height="31" patternUnits="userSpaceOnUse"><circle cx="7" cy="8" r="4" fill="#dfe7d4"/><circle cx="22" cy="23" r="3" fill="#e4eadb"/></pattern></defs><rect width="800" height="350" fill="url(#trees)"/><path d="M0 245 Q120 190 190 235 T370 215 T600 235 T800 205" fill="none" stroke="#f8f8f0" stroke-width="12"/><path d="M435 98 Q470 57 520 74 Q555 95 524 126 Q480 152 444 132 Z" fill="#c4dbda"/><path d="M544 250 Q590 226 616 266 Q600 302 560 291 Z" fill="#c4dbda"/>${coords.map(([x,y],i)=>`<g transform="translate(${x*8},${y*3.5}) rotate(${i%2?25:-20})"><ellipse rx="22" ry="42" fill="#d8e3bb"/><ellipse cy="-23" rx="13" ry="14" fill="#bfce9f"/><ellipse cx="18" cy="-10" rx="6" ry="11" fill="#eee8cb"/></g>`).join('')}<rect x="160" y="300" width="56" height="23" rx="4" fill="#d4cebb"/><path d="M154 301L188 285L222 301" fill="#adae94"/><text x="187" y="339" text-anchor="middle" fill="#8b9980" font-size="8">CLUBHOUSE</text></svg>${coords.map(([x,y],i)=>{const here=groups.filter(g=>g.hole===i+1);const severity=here.some(g=>state(g)==='late')?'late':here.some(g=>state(g)==='warn')?'warn':'';return `<button style="left:${x}%;top:${y}%" class="${severity}" data-hole="${i+1}" aria-label="Hole ${i+1}, ${here.length} groups">${i+1}</button>`;}).join('')}<div class="map-caption">Select a hole to see group details</div><div class="map-key">⚑ &nbsp; Pine Valley · Demo layout</div></div>`;}
function table(){const filtered=groups.filter(g=>(filter==='all'||(filter==='attention'?['warn','late'].includes(state(g)):state(g)===filter))&&g.name.toLowerCase().includes(search.toLowerCase()));return `<div class="panel groups-panel"><div class="panel-head"><div><h2>Groups on the course</h2><p>Every group, from first tee to final putt.</p></div><div class="table-tools"><input type="search" id="search" aria-label="Search groups" placeholder="⌕  Search groups" value="${search.replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;')}"><select id="filter" aria-label="Filter by pace"><option value="all">All groups</option><option value="attention">Needs attention</option><option value="good">On pace</option><option value="complete">Completed</option></select></div></div><div class="table-scroll"><table><thead><tr><th>GROUP</th><th>TEE TIME</th><th>CURRENT HOLE</th><th>PACE STATUS</th><th>EST. FINISH</th><th></th></tr></thead><tbody>${filtered.map(g=>`<tr><td><div class="group-name"><span class="group-badge">${String(g.id).padStart(2,'0')}</span><span><strong>${g.name}</strong><small>${g.players} players</small></span></div></td><td>${clock(g.tee)}</td><td>${g.hole>18?'Finished':`Hole ${g.hole} <span style="color:#a6af99">/ 18</span>`}</td><td>${pill(g)}</td><td>${clock(forecastFor(g).finish)}</td><td><button class="text-button" data-group="${g.id}" aria-label="View ${g.name}">View ↗</button></td></tr>`).join('')}</tbody></table>${!filtered.length?'<div class="empty">No groups match this filter.</div>':''}</div><div class="table-bottom"><span>Showing ${filtered.length} of ${groups.length} groups</span><span>Updated at ${clock(690+minutes)} · simulated</span></div></div>`;}
function alerts(){return groups.filter(g=>['late','warn'].includes(state(g))).sort((a,b)=>forecastFor(b).delay-forecastFor(a).delay);}
function overview(){const active=groups.filter(g=>g.hole<=18),attention=alerts(),avg=Math.round(groups.reduce((a,g)=>a+forecastFor(g).finish-g.tee,0)/groups.length);return `<div class="metrics"><div class="metric"><div class="metric-top">Groups on course <span class="metric-icon">♙</span></div><strong>${active.length} <small>/ ${groups.length} checked in</small></strong><div class="metric-bottom"><span class="positive">${active.reduce((a,g)=>a+g.players,0)} golfers</span> enjoying the course</div></div><div class="metric"><div class="metric-top">Projected average round <span class="metric-icon">◷</span></div><strong>${duration(avg)}</strong><div class="metric-bottom">Target ${duration(totalTarget)} <span class="caution">· ${Math.max(0,avg-totalTarget)}m over</span></div></div><div class="metric"><div class="metric-top">Groups on pace <span class="metric-icon">✓</span></div><strong>${active.filter(g=>state(g)==='good').length} <small>/ ${active.length} groups</small></strong><div class="metric-bottom"><span class="positive">Within 5 min</span> of hole targets</div></div><div class="metric"><div class="metric-top">Needs attention <span class="metric-icon">⚑</span></div><strong>${attention.length.toString().padStart(2,'0')} <small>groups</small></strong><div class="metric-bottom"><span class="caution">${attention.filter(g=>state(g)==='late').length} behind pace</span> · ${attention.filter(g=>state(g)==='warn').length} to watch</div></div></div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>The course, at a glance</h2><p>A little visibility goes a long way.</p></div><div class="legend"><span><b></b>On pace</span><span><b class="amber"></b>Watch</span><span><b class="red"></b>Behind</span></div></div>${courseMap()}<div class="traffic"><div class="traffic-heading"><b>Hole occupancy</b><span>Number of groups at each hole</span></div><div class="hole-strip">${holes.map((_,i)=>{const gs=groups.filter(g=>g.hole===i+1);return `<div class="hole-cell"><button data-hole="${i+1}" class="hole-bar ${gs.some(g=>state(g)==='late')?'hot':gs.length>1?'busy':''}" aria-label="View hole ${i+1}">${gs.length||'–'}</button>${i+1}</div>`;}).join('')}</div></div></section><aside class="insights"><section class="panel"><div class="panel-head"><div><h2>A little heads-up</h2><p>Where your attention matters.</p></div><span class="metric-icon">↗</span></div><div class="insight-content">${attention.slice(0,2).map(g=>`<div class="alert-item"><h3><span class="alert-icon">!</span> Hole ${g.hole} · ${forecastFor(g).delay} min behind</h3><p>${g.name} may need a marshal check-in.</p><button class="text-button" data-group="${g.id}">${notes.includes(g.id)?'Demo check-in logged ✓':'Review group →'}</button></div>`).join('')||'<div class="alert-item"><h3>All clear ✓</h3><p>Every active group is within the pace target.</p></div>'}<div class="alert-item"><h3><span class="alert-icon" style="background:#edf3e5;color:#758d5d">✓</span> Make room for a good round</h3><p>ETAs include the pace of each group and traffic ahead.</p><small>Estimates · updated when simulation advances</small></div></div></section><div class="reward-panel"><span class="tag">MONAD</span><span style="font-size:23px">◇</span><h3>Good pace deserves a little credit.</h3><p>Explore course-approved round badges, with Monad testnet planned.</p><button class="secondary" id="explore">Explore rewards ↗</button></div></aside></div>${table()}`;}
function player(){const g=groups.find(g=>g.id===selected)||groups[0],f=forecastFor(g);return `<div class="player-card"><div class="player-hero"><div style="display:flex;justify-content:space-between"><span style="font-size:11px">YOUR ROUND · DEMO</span><span>⚑</span></div><h2>${g.name}</h2><p>Pine Valley Golf Club · ${g.players} players</p></div><div class="player-body"><label for="player-group" style="font-size:10px">Preview as group </label><select id="player-group">${groups.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${x.name}</option>`).join('')}</select><div class="player-stats"><div><span>CURRENT HOLE</span><strong>${g.hole>18?'Done':g.hole}<small style="font-size:13px;color:#a4b294"> / 18</small></strong></div><div><span>EST. FINISH</span><strong>${clock(f.finish)}</strong></div><div><span>TIME LEFT</span><strong>${duration(f.remaining)}</strong></div></div><div class="progress"><div style="width:${Math.min(100,(g.hole-1)/18*100)}%"></div></div><p>${Math.min(18,g.hole-1)} of 18 holes complete · ${duration(g.elapsed)} elapsed</p><div style="margin:20px 0">${pill(g)}</div><div class="notice">${f.complete?'Your demo round is complete.':`Target for hole ${g.hole}: ${holes[g.hole-1]} minutes. ${f.delay>5?'Keep contact with the group ahead when it is safe to do so.':'Enjoy your round and keep an eye on the group ahead.'}`}</div><button class="primary" id="complete-hole" ${f.complete?'disabled':''}>${f.complete?'Round complete':'Check out of current hole →'}</button><p style="font-size:10px;margin-top:13px">Demo check-out advances this group to the next hole. GPS and real check-ins are not connected.</p></div></div>`;}
function rewards(){return `<div class="notice">Monad integration preview. No wallet is connected, no smart contract is deployed, and no tokens or badges are being issued.</div><div class="reward-layout"><section class="panel big-card"><div class="eyebrow">PLAY WELL. KEEP IT MOVING.</div><h2>A good round. A lasting badge.</h2><p>A course-approved pace badge can recognize groups that complete their round within the course target.</p><ol class="steps"><li>Finish the round and submit your check-ins.</li><li>Course staff review and attest to the result.</li><li>Claim a badge on Monad after wallet integration.</li></ol><button id="wallet-info" class="secondary">View integration requirements ↗</button></section><section class="panel big-card"><div class="badge-art">⚑</div><h2 class="badge-title">The Good Pace Club</h2><p style="text-align:center">Pine Valley · 18 holes · Target ${duration(totalTarget)}</p><div class="notice" style="margin-top:25px">Design preview only. Eligibility must be verified by the course; phone GPS alone cannot prove a completed round.</div></section></div>`;}
function render(){const titles={overview:['A clear view of every round.','Keep the course moving. Give every group a better day.'],groups:['Good rounds start with good timing.','Track every group, spot delays, and plan the next check-in.'],player:['Your round, at your pace.','A simple companion from the first tee to the clubhouse.'],rewards:['Good pace. Well earned.','A first look at course-approved rewards on Monad.']};$('#page-title').textContent=titles[view][0];$('#subtitle').textContent=titles[view][1];$('#breadcrumb').textContent=`Workspace / ${{overview:'Course overview',groups:'Groups & tee times',player:'Player view',rewards:'Monad rewards'}[view]}`;$('#sim-time').textContent=clock(690+minutes);$('#content').innerHTML=view==='overview'?overview():view==='groups'?table():view==='player'?player():rewards();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if($('#filter'))$('#filter').value=filter;}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').style.display='none',4000);}
function openGroup(id){const g=groups.find(g=>g.id===id),f=forecastFor(g);$('#detail-content').innerHTML=`<div class="eyebrow">GROUP ${String(g.id).padStart(2,'0')} · ${g.players} PLAYERS</div><h2 style="margin-top:10px">${g.name}</h2><p>Tee time ${clock(g.tee)} · ${duration(g.elapsed)} elapsed · ${f.complete?'Round complete':`Hole ${g.hole}`}</p><div style="margin-top:15px">${pill(g)} <span style="font-size:11px;margin-left:10px">Estimated finish ${clock(f.finish)}</span></div><h3>Upcoming hole ETAs</h3><p>Arrival estimates account for the group’s pace and traffic ahead.</p><div style="max-height:230px;overflow:auto;margin-top:12px"><table><thead><tr><th>HOLE</th><th>ARRIVAL</th><th>TARGET</th></tr></thead><tbody>${f.arrivals.map(h=>`<tr><td>Hole ${h.hole}</td><td>${h.current?'Currently playing':clock(h.at)}</td><td>${holes[h.hole-1]} min</td></tr>`).join('')||'<tr><td colspan="3">Round complete</td></tr>'}</tbody></table></div><button class="primary" style="margin-top:20px" data-note="${id}">${notes.includes(id)?'Demo check-in logged ✓':'Log demo marshal check-in'}</button>`;$('#detail').showModal();}
function openHole(h){const gs=groups.filter(g=>g.hole===h);$('#detail-content').innerHTML=`<div class="eyebrow">COURSE TRAFFIC</div><h2 style="margin-top:10px">Hole ${h}</h2><p>Target ${holes[h-1]} minutes · ${gs.length} group${gs.length!==1?'s':''} currently here</p>${gs.map(g=>`<div class="alert-item"><h3>${g.name}</h3><p>${g.players} players · ${g.inHole} min on hole · Finish ${clock(forecastFor(g).finish)}</p><div style="margin:10px 0">${pill(g)}</div><button class="secondary" data-open-group="${g.id}">View round ETAs →</button></div>`).join('')||'<div class="empty">This hole is clear in the simulation.</div>'}`;$('#detail').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;render();}if(b.id==='advance'){groups=advance(groups);minutes+=5;persist();render();toast('Simulation advanced by 5 minutes');}if(b.id==='reset'){groups=structuredClone(seed);minutes=0;notes=[];filter='all';search='';persist();render();toast('Demo reset');}if(b.dataset.group)openGroup(+b.dataset.group);if(b.dataset.hole)openHole(+b.dataset.hole);if(b.id==='close-dialog')$('#detail').close();if(b.dataset.openGroup){$('#detail').close();openGroup(+b.dataset.openGroup);}if(b.dataset.note){const id=+b.dataset.note;if(!notes.includes(id))notes.push(id);persist();b.textContent='Demo check-in logged ✓';toast('Demo check-in saved locally. No message was sent.');}if(b.id==='explore'){view='rewards';render();}if(b.id==='wallet-info'){ $('#detail-content').innerHTML='<h2>Connect Monad next</h2><p>The next build needs a wallet connection, a testnet badge contract, and a course attestation service. GPS and player details stay off-chain.</p><h3>Before issuing real badges</h3><p>Define course approval rules, verify wallet ownership, prevent duplicate claims, test transactions, and review the contract. No wallet keys belong in this repository.</p>';$('#detail').showModal();}if(b.id==='complete-hole'){groups=groups.map(g=>g.id===selected?{...g,hole:Math.min(19,g.hole+1),inHole:0}:g);persist();render();toast('Demo hole check-out saved');}});
document.addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;render();}if(e.target.id==='player-group'){selected=+e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
render();
